  app2.get("/api/analytics/product-usage-heatmap", async (req, res) => {
    try {
      const { level = "category", categories, usageAreas, suppliers: suppliers2, manufacturers, minPrice, maxPrice } = req.query;
      const products2 = await storage.getProducts();
      const treeNodes2 = await storage.getTreeNodes();
      const DEFAULT_USAGE_AREAS = [
        "Industrial",
        "Commercial",
        "Residential",
        "Infrastructure",
        "Food & Beverage",
        "Healthcare",
        "Parking",
        "Sports"
      ];
      const categoriesByLevel = treeNodes2.filter((n) => n.type === level);
      const filteredCategories = categories ? categoriesByLevel.filter((c) => categories.split(",").includes(c.nodeId)) : categoriesByLevel;
      const targetUsageAreas = usageAreas ? usageAreas.split(",") : DEFAULT_USAGE_AREAS;
      const filteredProducts = products2.filter((p) => {
        if (suppliers2 && !suppliers2.split(",").includes(p.supplier)) return false;
        if (manufacturers && !manufacturers.split(",").includes(p.manufacturer)) return false;
        if (minPrice && p.price < parseFloat(minPrice)) return false;
        if (maxPrice && p.price > parseFloat(maxPrice)) return false;
        return true;
      });
      const getProductCategory = (product) => {
        const findCategoryAtLevel = (nodeId) => {
          const node = treeNodes2.find((n) => n.nodeId === nodeId);
          if (!node) return void 0;
          if (node.type === level) return node;
          if (node.parentId) return findCategoryAtLevel(node.parentId);
          return void 0;
        };
        if (product.nodeId) {
          const node = treeNodes2.find((n) => n.nodeId === product.nodeId);
          if (node) return findCategoryAtLevel(node.nodeId);
        }
        if (product.category) {
          const cat = treeNodes2.find((n) => n.nodeId === product.category || n.name === product.category);
          if (cat) return findCategoryAtLevel(cat.nodeId);
        }
        return void 0;
      };
      const getProductUsageAreas = (product) => {
        const usageField = product.customFields?.find(
          (cf) => cf.fieldId?.toLowerCase().includes("usage") || cf.fieldId?.toLowerCase().includes("application")
        );
        if (usageField?.value) {
          return String(usageField.value).split(",").map((v) => v.trim());
        }
        return DEFAULT_USAGE_AREAS.slice(0, 2);
      };
      const heatmapData = filteredCategories.map((cat) => {
        const dataPoints = targetUsageAreas.map((area) => {
          const matchingProducts = filteredProducts.filter((p) => {
            const productCat = getProductCategory(p);
            if (!productCat || productCat.nodeId !== cat.nodeId) return false;
            return getProductUsageAreas(p).includes(area);
          });
          const prices = matchingProducts.map((p) => p.price).filter((p) => p > 0);
          const suppliersSet = new Set(matchingProducts.map((p) => p.supplier));
          const manufacturersSet = new Set(matchingProducts.map((p) => p.manufacturer).filter(Boolean));
          return {
            x: area,
            y: matchingProducts.length,
            meta: {
              productIds: matchingProducts.map((p) => p.id),
              suppliers: suppliersSet.size,
              manufacturers: manufacturersSet.size,
              avgPrice: prices.length > 0 ? prices.reduce((a, b) => a + b, 0) / prices.length : 0,
              minPrice: prices.length > 0 ? Math.min(...prices) : 0,
              maxPrice: prices.length > 0 ? Math.max(...prices) : 0
            }
          };
        });
        return {
          id: cat.name,
          categoryId: cat.nodeId,
          data: dataPoints
        };
      });
      res.json(heatmapData);
    } catch (error) {
      console.error("Error generating heatmap data:", error);
      res.status(500).json({ error: "Failed to generate heatmap data" });
    }
  });
