  app2.post("/api/backups/import", async (req, res) => {
    const MAX_IMPORT_SIZE = 50 * 1024 * 1024;
    let totalSize = 0;
    try {
      const chunks = [];
      req.on("data", (chunk) => {
        totalSize += chunk.length;
        if (totalSize > MAX_IMPORT_SIZE) {
          req.destroy();
          return res.status(413).json({ error: "Backup file too large (max 50MB)" });
        }
        chunks.push(chunk);
      });
      req.on("end", async () => {
        try {
          const buffer2 = Buffer.concat(chunks);
          const result = await importBackup(buffer2);
          if (result.success) {
            refreshState.trigger();
            res.status(201).json(result);
          } else {
            res.status(400).json(result);
          }
        } catch (error) {
          console.error("Error importing backup:", error);
          res.status(500).json({ error: "Failed to import backup" });
        }
      });
    } catch (error) {
      console.error("Error importing backup:", error);
      res.status(500).json({ error: "Failed to import backup" });
    }
  });
